import {readFile} from 'node:fs/promises';import {pathToFileURL} from 'node:url';import path from 'node:path';import assert from 'node:assert/strict';
const {PGlite}=await import(pathToFileURL(path.resolve(process.argv[2])).href),db=new PGlite();
try{await db.exec(`create role anon;create role authenticated;create table wc_orders(id uuid primary key,order_source text,wix_order_id text,order_number text,customer_name text);create table wc_order_items(id uuid primary key,order_id uuid references wc_orders(id) on delete cascade);create table wc_production_units(id uuid primary key,order_item_id uuid references wc_order_items(id) on delete cascade);`);await db.exec(`insert into wc_orders values('f076f530-6be8-458b-9606-693e0153c101','hub_test',null,'TEST-BACKDROP','White Corner internal test'),('f076f530-6be8-458b-9606-693e0153c102','hub_test',null,'TEST-CART','White Corner internal test'),('00000000-0000-4000-8000-000000000001','wix','real','10825','Real customer');insert into wc_order_items values('f076f530-6be8-458b-9606-693e0153c201','f076f530-6be8-458b-9606-693e0153c101');insert into wc_production_units values('f076f530-6be8-458b-9606-693e0153c301','f076f530-6be8-458b-9606-693e0153c201');`);await db.exec(await readFile('supabase/migrations/20260917000100_remove_retired_test_orders.sql','utf8'));assert.equal((await db.query('select count(*)::int n from wc_orders')).rows[0].n,1);assert.equal((await db.query('select count(*)::int n from wc_order_items')).rows[0].n,0);await assert.rejects(db.query("insert into wc_orders values('f076f530-6be8-458b-9606-693e0153c101','hub_test',null,'TEST-BACKDROP','White Corner internal test')"),/retired/);assert.equal((await db.query('select order_number from wc_orders')).rows[0].order_number,'10825');console.log('Exact deletion, cascade, recreation guard and real-order preservation passed.');}finally{await db.close();}
